contracts/protocols/dexes/uniswap/v2/Uni.content:
// SPDX-License-Identifier: BSL-1.1
pragma solidity ^0.8.0;

import {IERC20} from "@crane/contracts/interfaces/IERC20.sol";
import {IUniswapV2Pair} from "@crane/contracts/interfaces/protocols/dexes/uniswap/v2/IUniswapV2Pair.sol";
import {ERC20Repo} from "@crane/contracts/tokens/ERC20/ERC20Repo.sol";
import {ERC4626Repo} from "@crane/contracts/tokens/ERC4626/ERC4626Repo.sol";
import {UniswapV2FactoryAwareRepo} from "@crane/contracts/protocols/dexes/uniswap/v2/aware/UniswapV2FactoryAwareRepo.sol";
import {BetterMath} from "@crane/contracts/utils/math/BetterMath.sol";
import {ConstProdUtils} from "@crane/contracts/utils/math/ConstProdUtils.sol";
import {UniswapV2Utils} from "@crane/contracts/utils/math/UniswapV2Utils.sol";
import {UNISWAPV2_FEE_DENOMINATOR, UNISWAP_PROTOCOL_FEE_SHARE} from "@crane/contracts/constants/Constants.sol";
import {IStandardExchangeTransitionQuote} from "contracts/interfaces/IStandardExchangeTransitionQuote.sol";
import {VaultFeeOracleQueryAwareRepo} from "contracts/oracles/fee/VaultFeeOracleQueryAwareRepo.sol";
import {UniswapV2StandardExchangeCommon} from "contracts/protocols/dexes/uniswap/v2/UniswapV2StandardExchangeCommon.sol";

abstract contract UniswapV2StandardExchangeQuoteTarget is UniswapV2StandardExchangeCommon, IStandardExchangeTransitionQuote {
    struct QuoteState {
        address exchange;
        address asset;
        address holder;
        uint256 holderShares;
        uint256 actualLp;
        uint256 poolHeldLp;
        uint256 knownBalance;
        uint256 opposingBalance;
        UnIV2IndexSourceReserves pool;
        UniV2StrategyVault vault;
    }

    function quoteState(address asset_, address holder_) external view returns (bytes memory state_, uint256 holderAssets_) {
        QuoteState memory q;
        q.exchange = address(this);
        q.asset = asset_;
        q.holder = holder_;
        q.holderShares = IERC20(address(this)).balanceOf(holder_);
        q.pool.pool = IUniswapV2Pair(address(ERC4626Repo._reserveAsset()));
        bool lpAsset_ = asset_ == address(q.pool.pool);
        // LP-denominated claims still checkpoint the two pool legs in token0 order.
        _loadIndexSourceReserves(q.pool, lpAsset_ ? IERC20(address(0)) : IERC20(asset_));
        if (!lpAsset_ && asset_ != q.pool.token0 && asset_ != q.pool.token1) revert UnsupportedQuoteAsset(asset_);
        address known_ = lpAsset_ ? q.pool.token0 : asset_;
        _loadStrategyVault(q.vault, IERC20(known_));
        q.actualLp = q.pool.pool.balanceOf(address(this));
        q.poolHeldLp = q.pool.pool.balanceOf(address(q.pool.pool));
        q.knownBalance = IERC20(known_).balanceOf(address(q.pool.pool));
        q.opposingBalance = IERC20(known_ == q.pool.token0 ? q.pool.token1 : q.pool.token0).balanceOf(address(q.pool.pool));
        return (abi.encode(q), _quoteAssets(q, q.holderShares));
    }

    function quoteTransition(bytes calldata state_, Operation operation_, uint256 amount_)
        external view returns (bytes memory nextState_, uint256 amountIn_, uint256 amountOut_, uint256 holderAssetsAfter_)
    {
        QuoteState memory q = _decodeQuote(state_);
        if (operation_ == Operation.ReceiveShares) {
            q.holderShares += amount_;
            if (q.holderShares > q.vault.vaultTotalShares) revert InvalidQuoteState();
            return (abi.encode(q), amount_, amount_, _quoteAssets(q, q.holderShares));
        }
        _calcVaultFee(q.pool, q.vault);
        if (q.holder == address(VaultFeeOracleQueryAwareRepo._feeOracle().feeTo())) q.holderShares += q.vault.feeShares;
        amountIn_ = amount_;
        bool lpAsset_ = q.asset == address(q.pool.pool);
        if (operation_ == Operation.DepositExactIn) {
            if (!lpAsset_ && q.actualLp != q.vault.vaultLpReserve) revert InvalidQuoteState();
            uint256 lp_ = lpAsset_ ? amount_ : _quoteDeposit(q, amount_);
            amountOut_ = BetterMath._convertToSharesDown(
                lp_, lpAsset_ ? q.actualLp : q.vault.vaultLpReserve,
                q.vault.vaultTotalShares, ERC4626Repo._decimalOffset()
            );
            q.holderShares += amountOut_;
            q.vault.vaultTotalShares += amountOut_;
            q.actualLp += lp_;
        } else {
            uint256 lp_;
            if (operation_ == Operation.WithdrawExactOut) {
                lp_ = lpAsset_ ? amount_ : ConstProdUtils._quoteZapOutToTargetWithFee(
                    amount_, q.pool.totalSupply, q.pool.knownReserve, q.pool.opposingReserve,
                    q.pool.opTokenFeePercent, UNISWAPV2_FEE_DENOMINATOR, q.pool.kLast,
                    UNISWAP_PROTOCOL_FEE_SHARE, _quoteFeeTo() != address(0)
                );
                amountIn_ = BetterMath._convertToSharesUp(
                    lp_, q.vault.vaultLpReserve, q.vault.vaultTotalShares, ERC4626Repo._decimalOffset()
                );
            } else {
                lp_ = BetterMath._convertToAssetsDown(
                    amount_, q.vault.vaultLpReserve, q.vault.vaultTotalShares, ERC4626Repo._decimalOffset()
                );
            }
            if (amountIn_ > q.holderShares) revert InsufficientQuoteShares(amountIn_, q.holderShares);
            q.holderShares -= amountIn_;
            q.vault.vaultTotalShares -= amountIn_;
            q.actualLp -= lp_;
            amountOut_ = lpAsset_ ? lp_ : _quoteWithdraw(q, lp_);
        }
        q.vault.vaultLpReserve = q.actualLp;
        q.vault.knownTokenLastOwnedSourceReserve = BetterMath._mulDiv(q.actualLp, q.pool.knownReserve, q.pool.totalSupply);
        q.vault.opTokenLastOwnedSourceReserve = BetterMath._mulDiv(q.actualLp, q.pool.opposingReserve, q.pool.totalSupply);
        q.vault.feeShares = 0;
        return (abi.encode(q), amountIn_, amountOut_, _quoteAssets(q, q.holderShares));
    }

    function quoteAssets(bytes calldata state_, uint256 shares_) external view returns (uint256) {
        return _quoteAssets(_decodeQuote(state_), shares_);
    }

    function quoteExternalDeposit(bytes calldata state_, address tokenIn_, uint256 amountIn_)
        external view returns (bytes memory nextState_, uint256 sharesOut_, uint256 holderAssetsAfter_)
    {
        QuoteState memory q = _decodeQuote(state_);
        if (tokenIn_ == address(q.pool.pool)) {
            _calcVaultFee(q.pool, q.vault);
            if (q.holder == address(VaultFeeOracleQueryAwareRepo._feeOracle().feeTo())) q.holderShares += q.vault.feeShares;
            sharesOut_ = BetterMath._convertToSharesDown(
                amountIn_, q.actualLp, q.vault.vaultTotalShares, ERC4626Repo._decimalOffset()
            );
            q.vault.vaultTotalShares += sharesOut_;
            q.actualLp += amountIn_;
            q.vault.vaultLpReserve = q.actualLp;
            q.vault.knownTokenLastOwnedSourceReserve = BetterMath._mulDiv(q.actualLp, q.pool.knownReserve, q.pool.totalSupply);
            q.vault.opTokenLastOwnedSourceReserve = BetterMath._mulDiv(q.actualLp, q.pool.opposingReserve, q.pool.totalSupply);
            q.vault.feeShares = 0;
        } else {
            if (tokenIn_ != q.pool.token0 && tokenIn_ != q.pool.token1) revert UnsupportedQuoteAsset(tokenIn_);
            address accounting_ = q.asset;
            if (q.asset == address(q.pool.pool)) q.asset = q.pool.token0;
            bool flipped = tokenIn_ != q.asset;
            if (flipped) _flipQuoteAsset(q);
            (bytes memory projected,, uint256 minted,) = IStandardExchangeTransitionQuote(address(this)).quoteTransition(
                abi.encode(q), Operation.DepositExactIn, amountIn_
            );
            q = abi.decode(projected, (QuoteState));
            q.holderShares -= minted;
            sharesOut_ = minted;
            if (flipped) _flipQuoteAsset(q);
            q.asset = accounting_;
        }
        return (abi.encode(q), sharesOut_, _quoteAssets(q, q.holderShares));
    }

    function _flipQuoteAsset(QuoteState memory q) private pure {
        q.asset = q.asset == q.pool.token0 ? q.pool.token1 : q.pool.token0;
        (q.knownBalance, q.opposingBalance) = (q.opposingBalance, q.knownBalance);
        (q.pool.knownReserve, q.pool.opposingReserve) = (q.pool.opposingReserve, q.pool.knownReserve);
        (q.pool.knownfeePercent, q.pool.opTokenFeePercent) = (q.pool.opTokenFeePercent, q.pool.knownfeePercent);
        (q.vault.knownTokenLastOwnedSourceReserve, q.vault.opTokenLastOwnedSourceReserve) =
            (q.vault.opTokenLastOwnedSourceReserve, q.vault.knownTokenLastOwnedSourceReserve);
    }

    function quoteExternalExchange(bytes calldata state_, address tokenIn_, uint256 amountIn_)
        external view returns (bytes memory nextState_, uint256 amountOut_, uint256 holderAssetsAfter_)
    {
        QuoteState memory q = _decodeQuote(state_);
        address opposing_ = q.asset == q.pool.token0 ? q.pool.token1 : q.pool.token0;
        if (q.asset == address(q.pool.pool)) {
            if (tokenIn_ != q.pool.token0 && tokenIn_ != q.pool.token1) revert UnsupportedQuoteAsset(tokenIn_);
            q.asset = q.pool.token0;
            bool flipped = tokenIn_ != q.asset;
            if (flipped) _flipQuoteAsset(q);
            amountOut_ = _quoteDeposit(q, amountIn_);
            if (flipped) _flipQuoteAsset(q);
            q.asset = address(q.pool.pool);
            // The live pass-through returns newly minted LP to its caller and
            // rejects any change to the SE's held LP, including pool fee LP.
            if (q.actualLp != q.vault.vaultLpReserve) revert InvalidQuoteState();
        } else if (tokenIn_ == address(q.pool.pool)) {
            // These LP tokens belong to the separate caller. Retain the SE's own
            // LP and fee checkpoints; only the shared pool state changes.
            amountOut_ = _quoteWithdraw(q, amountIn_);
            if (q.actualLp != q.vault.vaultLpReserve) revert InvalidQuoteState();
        } else if (tokenIn_ == opposing_) {
            amountOut_ = ConstProdUtils._saleQuote(
                amountIn_, q.pool.opposingReserve, q.pool.knownReserve,
                q.pool.opTokenFeePercent, UNISWAPV2_FEE_DENOMINATOR
            );
            q.knownBalance -= amountOut_;
            q.opposingBalance += amountIn_;
            q.pool.knownReserve = q.knownBalance;
            q.pool.opposingReserve = q.opposingBalance;
        } else revert UnsupportedQuoteAsset(tokenIn_);
        return (abi.encode(q), amountOut_, _quoteAssets(q, q.holderShares));
    }

    function quoteTotalSupply(bytes calldata state_) external view returns (uint256) {
        return _decodeQuote(state_).vault.vaultTotalShares;
    }

    function quoteShareBalance(bytes calldata state_) external view returns (uint256) {
        return _decodeQuote(state_).holderShares;
    }

    function _decodeQuote(bytes calldata state_) private view returns (QuoteState memory q) {
        q = abi.decode(state_, (QuoteState));
        if (q.exchange != address(this) || address(q.pool.pool) != address(ERC4626Repo._reserveAsset())) revert InvalidQuoteState();
    }

    function _quoteAssets(QuoteState memory q, uint256 shares_) private view returns (uint256) {
        UniV2StrategyVault memory v = abi.decode(abi.encode(q.vault), (UniV2StrategyVault));
        _calcVaultFee(q.pool, v);
        uint256 lp_ = BetterMath._convertToAssetsDown(shares_, v.vaultLpReserve, v.vaultTotalShares, ERC4626Repo._decimalOffset());
        if (q.asset == address(q.pool.pool)) return lp_;
        return UniswapV2Utils._quoteWithdrawSwapFee(
            lp_, q.pool.totalSupply, q.pool.knownReserve, q.pool.opposingReserve, q.pool.opTokenFeePercent,
            UNISWAPV2_FEE_DENOMINATOR, q.pool.kLast, _quoteFeeTo() != address(0)
        );
    }

    function _quoteFeeTo() private view returns (address) {
        return UniswapV2FactoryAwareRepo._uniswapV2Factory().feeTo();
    }

    function _quoteMintPoolFee(QuoteState memory q) private view returns (uint256 fee_) {
        address recipient_ = _quoteFeeTo();
        if (recipient_ != address(0)) {
            fee_ = ConstProdUtils._calculateProtocolFee(
                q.pool.totalSupply, q.pool.knownReserve * q.pool.opposingReserve, q.pool.kLast,
                UNISWAP_PROTOCOL_FEE_SHARE
            );
            q.pool.totalSupply += fee_;
            if (recipient_ == address(this)) q.actualLp += fee_;
            if (recipient_ == address(q.pool.pool)) q.poolHeldLp += fee_;
        } else q.pool.kLast = 0;
    }

    function _quoteDeposit(QuoteState memory q, uint256 amount_) private view returns (uint256 lp_) {
        uint256 sold_ = ConstProdUtils._swapDepositSaleAmt(amount_, q.pool.knownReserve, q.pool.knownfeePercent);
        uint256 other_ = ConstProdUtils._saleQuote(
            sold_, q.pool.knownReserve, q.pool.opposingReserve, q.pool.knownfeePercent, UNISWAPV2_FEE_DENOMINATOR
        );
        q.knownBalance += sold_;
        q.opposingBalance -= other_;
        q.pool.knownReserve = q.knownBalance;
        q.pool.opposingReserve = q.opposingBalance;
        uint256 known_ = amount_ - sold_;
        uint256 optimal_ = BetterMath._mulDiv(known_, q.pool.opposingReserve, q.pool.knownReserve);
        if (optimal_ <= other_) other_ = optimal_;
        else known_ = BetterMath._mulDiv(other_, q.pool.knownReserve, q.pool.opposingReserve);
        _quoteMintPoolFee(q);
        lp_ = BetterMath._min(
            BetterMath._mulDiv(known_, q.pool.totalSupply, q.pool.knownReserve),
            BetterMath._mulDiv(other_, q.pool.totalSupply, q.pool.opposingReserve)
        );
        q.pool.totalSupply += lp_;
        q.knownBalance += known_;
        q.opposingBalance += other_;
        q.pool.knownReserve = q.knownBalance;
        q.pool.opposingReserve = q.opposingBalance;
        if (_quoteFeeTo() != address(0)) q.pool.kLast = q.pool.knownReserve * q.pool.opposingReserve;
    }

    function _quoteWithdraw(QuoteState memory q, uint256 lp_) private view returns (uint256 assets_) {
        uint256 burned_ = lp_ + q.poolHeldLp;
        _quoteMintPoolFee(q);
        q.poolHeldLp -= burned_ - lp_;
        uint256 known_ = BetterMath._mulDiv(burned_, q.knownBalance, q.pool.totalSupply);
        uint256 other_ = BetterMath._mulDiv(burned_, q.opposingBalance, q.pool.totalSupply);
        q.pool.totalSupply -= burned_;
        q.knownBalance -= known_;
        q.opposingBalance -= other_;
        q.pool.knownReserve = q.knownBalance;
        q.pool.opposingReserve = q.opposingBalance;
        if (_quoteFeeTo() != address(0)) q.pool.kLast = q.pool.knownReserve * q.pool.opposingReserve;
        uint256 proceeds_ = ConstProdUtils._saleQuote(
            other_, q.pool.opposingReserve, q.pool.knownReserve, q.pool.opTokenFeePercent, UNISWAPV2_FEE_DENOMINATOR
        );
        q.knownBalance -= proceeds_;
        q.opposingBalance += other_;
        q.pool.knownReserve = q.knownBalance;
        q.pool.opposingReserve = q.opposingBalance;
        return known_ + proceeds_;
    }
}

contracts/protocols/dexes/camelot/v2/Cam.content:
// SPDX-License-Identifier: BSL-1.1
pragma solidity ^0.8.0;

import {IERC20} from "@crane/contracts/interfaces/IERC20.sol";
import {ICamelotPair} from "@crane/contracts/interfaces/protocols/dexes/camelot/v2/ICamelotPair.sol";
import {ERC20Repo} from "@crane/contracts/tokens/ERC20/ERC20Repo.sol";
import {ERC4626Repo} from "@crane/contracts/tokens/ERC4626/ERC4626Repo.sol";
import {CamelotV2FactoryAwareRepo} from "@crane/contracts/protocols/dexes/camelot/v2/CamelotV2FactoryAwareRepo.sol";
import {BetterMath} from "@crane/contracts/utils/math/BetterMath.sol";
import {ConstProdUtils} from "@crane/contracts/utils/math/ConstProdUtils.sol";
import {CamelotV2Utils} from "@crane/contracts/utils/math/CamelotV2Utils.sol";
import {CAMELOTV2_FEE_DENOMINATOR} from "@crane/contracts/constants/Constants.sol";
import {Math} from "@crane/contracts/utils/Math.sol";
import {IStandardExchangeTransitionQuote} from "contracts/interfaces/IStandardExchangeTransitionQuote.sol";
import {VaultFeeOracleQueryAwareRepo} from "contracts/oracles/fee/VaultFeeOracleQueryAwareRepo.sol";
import {CamelotV2StandardExchangeCommon} from "contracts/protocols/dexes/camelot/v2/CamelotV2StandardExchangeCommon.sol";

abstract contract CamelotV2StandardExchangeQuoteTarget is CamelotV2StandardExchangeCommon, IStandardExchangeTransitionQuote {
    struct QuoteState {
        address exchange;
        address asset;
        address holder;
        uint256 holderShares;
        uint256 actualLp;
        uint256 poolHeldLp;
        uint256 knownBalance;
        uint256 opposingBalance;
        CamelotV2IndexSourceReserves pool;
        CamelotV2StrategyVault vault;
    }

    function quoteState(address asset_, address holder_) external view returns (bytes memory state_, uint256 holderAssets_) {
        QuoteState memory q;
        q.exchange = address(this);
        q.asset = asset_;
        q.holder = holder_;
        q.holderShares = IERC20(address(this)).balanceOf(holder_);
        q.pool.pool = ICamelotPair(address(ERC4626Repo._reserveAsset()));
        bool lpAsset_ = asset_ == address(q.pool.pool);
        // LP-denominated claims still checkpoint the two pool legs in token0 order.
        _loadIndexSourceReserves(q.pool, lpAsset_ ? IERC20(address(0)) : IERC20(asset_));
        if (!lpAsset_ && asset_ != q.pool.token0 && asset_ != q.pool.token1) revert UnsupportedQuoteAsset(asset_);
        address known_ = lpAsset_ ? q.pool.token0 : asset_;
        _loadStrategyVault(q.vault, IERC20(known_));
        q.actualLp = q.pool.pool.balanceOf(address(this));
        q.poolHeldLp = q.pool.pool.balanceOf(address(q.pool.pool));
        q.knownBalance = IERC20(known_).balanceOf(address(q.pool.pool));
        q.opposingBalance = IERC20(known_ == q.pool.token0 ? q.pool.token1 : q.pool.token0).balanceOf(address(q.pool.pool));
        return (abi.encode(q), _quoteAssets(q, q.holderShares));
    }

    function quoteTransition(bytes calldata state_, Operation operation_, uint256 amount_)
        external view returns (bytes memory nextState_, uint256 amountIn_, uint256 amountOut_, uint256 holderAssetsAfter_)
    {
        QuoteState memory q = _decodeQuote(state_);
        if (operation_ == Operation.ReceiveShares) {
            q.holderShares += amount_;
            if (q.holderShares > q.vault.vaultTotalShares) revert InvalidQuoteState();
            return (abi.encode(q), amount_, amount_, _quoteAssets(q, q.holderShares));
        }
        _calcVaultFee(q.pool, q.vault);
        if (q.holder == address(VaultFeeOracleQueryAwareRepo._feeOracle().feeTo())) q.holderShares += q.vault.feeShares;
        amountIn_ = amount_;
        bool lpAsset_ = q.asset == address(q.pool.pool);
        if (operation_ == Operation.DepositExactIn) {
            if (!lpAsset_ && q.actualLp != q.vault.vaultLpReserve) revert InvalidQuoteState();
            if (lpAsset_ && q.vault.vaultTotalShares == 0 && q.actualLp > q.vault.vaultLpReserve) revert InvalidQuoteState();
            uint256 lp_ = lpAsset_ ? amount_ : _quoteDeposit(q, amount_);
            amountOut_ = BetterMath._convertToSharesDown(
                lp_, lpAsset_ ? q.actualLp : q.vault.vaultLpReserve,
                q.vault.vaultTotalShares, ERC4626Repo._decimalOffset()
            );
            q.holderShares += amountOut_;
            q.vault.vaultTotalShares += amountOut_;
            q.actualLp += lp_;
        } else {
            uint256 lp_;
            if (operation_ == Operation.WithdrawExactOut) {
                lp_ = lpAsset_ ? amount_ : ConstProdUtils._quoteZapOutToTargetWithFee(
                    amount_, q.pool.totalSupply, q.pool.knownReserve, q.pool.opposingReserve,
                    q.pool.opTokenFeePercent, CAMELOTV2_FEE_DENOMINATOR, q.pool.kLast,
                    _quoteOwnerFee(), _quoteFeeTo() != address(0)
                );
                amountIn_ = BetterMath._convertToSharesUp(
                    lp_, q.vault.vaultLpReserve, q.vault.vaultTotalShares, ERC4626Repo._decimalOffset()
                );
            } else {
                lp_ = BetterMath._convertToAssetsDown(
                    amount_, q.vault.vaultLpReserve, q.vault.vaultTotalShares, ERC4626Repo._decimalOffset()
                );
            }
            if (amountIn_ > q.holderShares) revert InsufficientQuoteShares(amountIn_, q.holderShares);
            q.holderShares -= amountIn_;
            q.vault.vaultTotalShares -= amountIn_;
            q.actualLp -= lp_;
            amountOut_ = lpAsset_ ? lp_ : _quoteWithdraw(q, lp_);
        }
        q.vault.vaultLpReserve = q.actualLp;
        q.vault.knownTokenLastOwnedSourceReserve = BetterMath._mulDiv(q.actualLp, q.pool.knownReserve, q.pool.totalSupply);
        q.vault.opTokenLastOwnedSourceReserve = BetterMath._mulDiv(q.actualLp, q.pool.opposingReserve, q.pool.totalSupply);
        q.vault.feeShares = 0;
        return (abi.encode(q), amountIn_, amountOut_, _quoteAssets(q, q.holderShares));
    }

    function quoteAssets(bytes calldata state_, uint256 shares_) external view returns (uint256) {
        return _quoteAssets(_decodeQuote(state_), shares_);
    }

    function quoteExternalDeposit(bytes calldata state_, address tokenIn_, uint256 amountIn_)
        external view returns (bytes memory nextState_, uint256 sharesOut_, uint256 holderAssetsAfter_)
    {
        QuoteState memory q = _decodeQuote(state_);
        if (tokenIn_ == address(q.pool.pool)) {
            _calcVaultFee(q.pool, q.vault);
            if (q.holder == address(VaultFeeOracleQueryAwareRepo._feeOracle().feeTo())) q.holderShares += q.vault.feeShares;
            if (q.vault.vaultTotalShares == 0 && q.actualLp > q.vault.vaultLpReserve) revert InvalidQuoteState();
            sharesOut_ = BetterMath._convertToSharesDown(
                amountIn_, q.actualLp, q.vault.vaultTotalShares, ERC4626Repo._decimalOffset()
            );
            q.vault.vaultTotalShares += sharesOut_;
            q.actualLp += amountIn_;
            q.vault.vaultLpReserve = q.actualLp;
            q.vault.knownTokenLastOwnedSourceReserve = BetterMath._mulDiv(q.actualLp, q.pool.knownReserve, q.pool.totalSupply);
            q.vault.opTokenLastOwnedSourceReserve = BetterMath._mulDiv(q.actualLp, q.pool.opposingReserve, q.pool.totalSupply);
            q.vault.feeShares = 0;
        } else {
            if (tokenIn_ != q.pool.token0 && tokenIn_ != q.pool.token1) revert UnsupportedQuoteAsset(tokenIn_);
            address accounting_ = q.asset;
            if (q.asset == address(q.pool.pool)) q.asset = q.pool.token0;
            bool flipped = tokenIn_ != q.asset;
            if (flipped) _flipQuoteAsset(q);
            (bytes memory projected,, uint256 minted,) = IStandardExchangeTransitionQuote(address(this)).quoteTransition(
                abi.encode(q), Operation.DepositExactIn, amountIn_
            );
            q = abi.decode(projected, (QuoteState));
            q.holderShares -= minted;
            sharesOut_ = minted;
            if (flipped) _flipQuoteAsset(q);
            q.asset = accounting_;
        }
        return (abi.encode(q), sharesOut_, _quoteAssets(q, q.holderShares));
    }

    function _flipQuoteAsset(QuoteState memory q) private pure {
        q.asset = q.asset == q.pool.token0 ? q.pool.token1 : q.pool.token0;
        (q.knownBalance, q.opposingBalance) = (q.opposingBalance, q.knownBalance);
        (q.pool.knownReserve, q.pool.opposingReserve) = (q.pool.opposingReserve, q.pool.knownReserve);
        (q.pool.knownfeePercent, q.pool.opTokenFeePercent) = (q.pool.opTokenFeePercent, q.pool.knownfeePercent);
        (q.vault.knownTokenLastOwnedSourceReserve, q.vault.opTokenLastOwnedSourceReserve) =
            (q.vault.opTokenLastOwnedSourceReserve, q.vault.knownTokenLastOwnedSourceReserve);
    }

    function quoteExternalExchange(bytes calldata state_, address tokenIn_, uint256 amountIn_)
        external view returns (bytes memory nextState_, uint256 amountOut_, uint256 holderAssetsAfter_)
    {
        QuoteState memory q = _decodeQuote(state_);
        address opposing_ = q.asset == q.pool.token0 ? q.pool.token1 : q.pool.token0;
        if (q.asset == address(q.pool.pool)) {
            if (tokenIn_ != q.pool.token0 && tokenIn_ != q.pool.token1) revert UnsupportedQuoteAsset(tokenIn_);
            q.asset = q.pool.token0;
            bool flipped = tokenIn_ != q.asset;
            if (flipped) _flipQuoteAsset(q);
            amountOut_ = _quoteDeposit(q, amountIn_);
            if (flipped) _flipQuoteAsset(q);
            q.asset = address(q.pool.pool);
            // The live pass-through returns newly minted LP to its caller and
            // rejects any change to the SE's held LP, including pool fee LP.
            if (q.actualLp != q.vault.vaultLpReserve) revert InvalidQuoteState();
        } else if (tokenIn_ == address(q.pool.pool)) {
            // These LP tokens belong to the separate caller. Retain the SE's own
            // LP and fee checkpoints; only the shared pool state changes.
            amountOut_ = _quoteWithdraw(q, amountIn_);
            // The live pass-through route rejects any change to the SE's
            // booked LP, including protocol-fee LP minted to this vault.
            if (q.actualLp != q.vault.vaultLpReserve) revert InvalidQuoteState();
        } else if (tokenIn_ == opposing_) {
            amountOut_ = ConstProdUtils._saleQuote(
                amountIn_, q.pool.opposingReserve, q.pool.knownReserve,
                q.pool.opTokenFeePercent, CAMELOTV2_FEE_DENOMINATOR
            );
            _flipQuoteAsset(q);
            _quotePoolSwap(q, amountIn_);
            _flipQuoteAsset(q);
        } else revert UnsupportedQuoteAsset(tokenIn_);
        return (abi.encode(q), amountOut_, _quoteAssets(q, q.holderShares));
    }

    function quoteTotalSupply(bytes calldata state_) external view returns (uint256) {
        return _decodeQuote(state_).vault.vaultTotalShares;
    }

    function quoteShareBalance(bytes calldata state_) external view returns (uint256) {
        return _decodeQuote(state_).holderShares;
    }

    function _decodeQuote(bytes calldata state_) private view returns (QuoteState memory q) {
        q = abi.decode(state_, (QuoteState));
        if (q.exchange != address(this) || address(q.pool.pool) != address(ERC4626Repo._reserveAsset())) revert InvalidQuoteState();
    }

    function _quoteAssets(QuoteState memory q, uint256 shares_) private view returns (uint256) {
        CamelotV2StrategyVault memory v = abi.decode(abi.encode(q.vault), (CamelotV2StrategyVault));
        _calcVaultFee(q.pool, v);
        uint256 lp_ = BetterMath._convertToAssetsDown(shares_, v.vaultLpReserve, v.vaultTotalShares, ERC4626Repo._decimalOffset());
        if (q.asset == address(q.pool.pool)) return lp_;
        return CamelotV2Utils._quoteWithdrawSwapWithFee(
            lp_, q.pool.totalSupply, q.pool.knownReserve, q.pool.opposingReserve, q.pool.opTokenFeePercent,
            CAMELOTV2_FEE_DENOMINATOR, q.pool.kLast, _quoteOwnerFee(), _quoteFeeTo() != address(0)
        );
    }

    function _quoteFeeTo() private view returns (address) {
        return CamelotV2FactoryAwareRepo._camelotV2Factory().feeTo();
    }

    function _quoteOwnerFee() private view returns (uint256) {
        return CamelotV2FactoryAwareRepo._camelotV2Factory().ownerFeeShare();
    }

    function _quoteReferralFee(QuoteState memory q, uint256 amount_, uint256 fee_) private view returns (uint256) {
        address referrer_ = address(VaultFeeOracleQueryAwareRepo._feeOracle().feeTo());
        if (referrer_ == address(0) || referrer_ == address(q.pool.pool)) return 0;
        uint256 share_ = CamelotV2FactoryAwareRepo._camelotV2Factory().referrersFeeShare(referrer_);
        return amount_ * share_ * fee_ / (CAMELOTV2_FEE_DENOMINATOR ** 2);
    }

    function _quotePoolSwap(QuoteState memory q, uint256 amount_) private view {
        uint256 input_ = q.knownBalance + amount_ - q.pool.knownReserve;
        uint256 opposingInput_ = q.opposingBalance - q.pool.opposingReserve;
        uint256 output_ = ConstProdUtils._saleQuote(
            input_, q.pool.knownReserve, q.pool.opposingReserve,
            q.pool.knownfeePercent, CAMELOTV2_FEE_DENOMINATOR
        );
        q.knownBalance += amount_;
        q.knownBalance -= _quoteReferralFee(q, input_, q.pool.knownfeePercent);
        q.opposingBalance -= output_ + _quoteReferralFee(q, opposingInput_, q.pool.opTokenFeePercent);
        q.pool.knownReserve = q.knownBalance;
        q.pool.opposingReserve = q.opposingBalance;
    }

    function _quoteMintPoolFee(QuoteState memory q) private view returns (uint256 fee_) {
        address recipient_ = _quoteFeeTo();
        if (recipient_ != address(0)) {
            // Match the pool's integer owner-fee denominator, including
            // 16666/16667; these must not select Uniswap's special formula.
            if (q.pool.kLast != 0) {
                uint256 rootK_ = Math.sqrt(q.pool.knownReserve * q.pool.opposingReserve);
                uint256 rootLast_ = Math.sqrt(q.pool.kLast);
                if (rootK_ > rootLast_) {
                    uint256 factor_ = CAMELOTV2_FEE_DENOMINATOR * 100 / _quoteOwnerFee() - 100;
                    fee_ = q.pool.totalSupply * (rootK_ - rootLast_) * 100
                        / (rootK_ * factor_ + rootLast_ * 100);
                }
            }
            q.pool.totalSupply += fee_;
            if (recipient_ == address(this)) q.actualLp += fee_;
            if (recipient_ == address(q.pool.pool)) q.poolHeldLp += fee_;
        } else q.pool.kLast = 0;
    }

    function _quoteDeposit(QuoteState memory q, uint256 amount_) private view returns (uint256 lp_) {
        uint256 sold_ = ConstProdUtils._swapDepositSaleAmt(amount_, q.pool.knownReserve, q.pool.knownfeePercent);
        uint256 other_ = ConstProdUtils._saleQuote(
            sold_, q.pool.knownReserve, q.pool.opposingReserve, q.pool.knownfeePercent, CAMELOTV2_FEE_DENOMINATOR
        );
        // The service deposits its quoted proceeds. The router separately
        // consumes any input-side pool donation when executing the swap.
        _quotePoolSwap(q, sold_);
        uint256 known_ = amount_ - sold_;
        uint256 optimal_ = BetterMath._mulDiv(known_, q.pool.opposingReserve, q.pool.knownReserve);
        if (optimal_ <= other_) other_ = optimal_;
        else known_ = BetterMath._mulDiv(other_, q.pool.knownReserve, q.pool.opposingReserve);
        _quoteMintPoolFee(q);
        lp_ = BetterMath._min(
            BetterMath._mulDiv(known_, q.pool.totalSupply, q.pool.knownReserve),
            BetterMath._mulDiv(other_, q.pool.totalSupply, q.pool.opposingReserve)
        );
        q.pool.totalSupply += lp_;
        q.knownBalance += known_;
        q.opposingBalance += other_;
        q.pool.knownReserve = q.knownBalance;
        q.pool.opposingReserve = q.opposingBalance;
        if (_quoteFeeTo() != address(0)) q.pool.kLast = q.pool.knownReserve * q.pool.opposingReserve;
    }

    function _quoteWithdraw(QuoteState memory q, uint256 lp_) private view returns (uint256 assets_) {
        uint256 burned_ = lp_ + q.poolHeldLp;
        _quoteMintPoolFee(q);
        q.poolHeldLp -= burned_ - lp_;
        uint256 known_ = BetterMath._mulDiv(burned_, q.knownBalance, q.pool.totalSupply);
        uint256 other_ = BetterMath._mulDiv(burned_, q.opposingBalance, q.pool.totalSupply);
        q.pool.totalSupply -= burned_;
        q.knownBalance -= known_;
        q.opposingBalance -= other_;
        q.pool.knownReserve = q.knownBalance;
        q.pool.opposingReserve = q.opposingBalance;
        if (_quoteFeeTo() != address(0)) q.pool.kLast = q.pool.knownReserve * q.pool.opposingReserve;
        uint256 proceeds_ = ConstProdUtils._saleQuote(
            other_, q.pool.opposingReserve, q.pool.knownReserve, q.pool.opTokenFeePercent, CAMELOTV2_FEE_DENOMINATOR
        );
        q.knownBalance -= proceeds_;
        q.opposingBalance += other_ - _quoteReferralFee(q, other_, q.pool.opTokenFeePercent);
        q.pool.knownReserve = q.knownBalance;
        q.pool.opposingReserve = q.opposingBalance;
        return known_ + proceeds_;
    }
}

contracts/protocols/dexes/aerodrome/v1/A.content:
// SPDX-License-Identifier: BSL-1.1
pragma solidity ^0.8.0;

import {IERC20} from "@crane/contracts/interfaces/IERC20.sol";
import {IPool} from "@crane/contracts/interfaces/protocols/dexes/aerodrome/IPool.sol";
import {ERC20Repo} from "@crane/contracts/tokens/ERC20/ERC20Repo.sol";
import {ERC4626Repo} from "@crane/contracts/tokens/ERC4626/ERC4626Repo.sol";
import {AerodromePoolMetadataRepo} from "@crane/contracts/protocols/dexes/aerodrome/v1/aware/AerodromePoolMetadataRepo.sol";
import {BetterMath} from "@crane/contracts/utils/math/BetterMath.sol";
import {ConstProdUtils} from "@crane/contracts/utils/math/ConstProdUtils.sol";
import {AerodromeUtils} from "@crane/contracts/utils/math/AerodromeUtils.sol";
import {Math} from "@crane/contracts/utils/Math.sol";
import {IStandardExchangeTransitionQuote, IStandardExchangeExternalQuote} from "contracts/interfaces/IStandardExchangeTransitionQuote.sol";
import {VaultFeeOracleQueryAwareRepo} from "contracts/oracles/fee/VaultFeeOracleQueryAwareRepo.sol";
import {AerodromeStandardExchangeRepo} from "contracts/protocols/dexes/aerodrome/v1/AerodromeStandardExchangeRepo.sol";
import {AerodromeStandardExchangeCommon} from "contracts/protocols/dexes/aerodrome/v1/AerodromeStandardExchangeCommon.sol";

/// @notice Sequential volatile-pool quotes, including separately collected LP fees.
abstract contract AerodromeStandardExchangeQuoteTarget is
    AerodromeStandardExchangeCommon, IStandardExchangeTransitionQuote, IStandardExchangeExternalQuote
{
    struct QuoteState {
        address exchange;
        address asset;
        address holder;
        address pool;
        address[2] tokens;
        uint256 holderShares;
        uint256 supply;
        uint256 actualLp;
        uint256 bookedLp;
        uint256 poolSupply;
        uint256 poolHeldLp;
        uint256[2] reserves;
        uint256[2] balances;
        uint256[2] indexes;
        uint256[2] suppliedIndexes;
        uint256[2] claimable;
        uint256[2] excess;
    }

    function quoteState(address asset, address holder) external view returns (bytes memory, uint256) {
        QuoteState memory q;
        q.exchange = address(this);
        q.asset = asset;
        q.holder = holder;
        q.pool = address(ERC4626Repo._reserveAsset());
        IPool pool = IPool(q.pool);
        q.tokens = [pool.token0(), pool.token1()];
        if (asset != q.pool && asset != q.tokens[0] && asset != q.tokens[1]) revert UnsupportedQuoteAsset(asset);
        q.holderShares = IERC20(address(this)).balanceOf(holder);
        q.supply = ERC20Repo._totalSupply();
        q.actualLp = IERC20(q.pool).balanceOf(address(this));
        q.bookedLp = ERC4626Repo._lastTotalAssets();
        q.poolSupply = IERC20(q.pool).totalSupply();
        q.poolHeldLp = IERC20(q.pool).balanceOf(q.pool);
        (q.reserves[0], q.reserves[1],) = pool.getReserves();
        q.balances = [IERC20(q.tokens[0]).balanceOf(q.pool), IERC20(q.tokens[1]).balanceOf(q.pool)];
        q.indexes = [pool.index0(), pool.index1()];
        q.suppliedIndexes = [pool.supplyIndex0(address(this)), pool.supplyIndex1(address(this))];
        q.claimable = [pool.claimable0(address(this)), pool.claimable1(address(this))];
        q.excess = [AerodromeStandardExchangeRepo._excessToken0(), AerodromeStandardExchangeRepo._excessToken1()];
        return (abi.encode(q), _aeroAssets(q, q.holderShares));
    }

    function _readAeroQuote(bytes calldata state) private view returns (QuoteState memory q) {
        q = abi.decode(state, (QuoteState));
        if (q.exchange != address(this) || q.pool != address(ERC4626Repo._reserveAsset())) revert InvalidQuoteState();
        if (q.asset != q.pool && q.asset != q.tokens[0] && q.asset != q.tokens[1]) revert InvalidQuoteState();
    }

    function _aeroFee(QuoteState memory q) private view returns (uint256) {
        return AerodromePoolMetadataRepo._factory().getFee(q.pool, false);
    }

    function quoteAssets(bytes calldata state, uint256 shares) external view returns (uint256) {
        return _aeroAssets(_readAeroQuote(state), shares);
    }

    function quoteShareBalance(bytes calldata state) external view returns (uint256) {
        return _readAeroQuote(state).holderShares;
    }

    function quoteTotalSupply(bytes calldata state) external view returns (uint256) {
        return _readAeroQuote(state).supply;
    }

    /// @dev Preserve the public SE redemption convention: preview a fee compound
    /// and then quote the proportional LP burn and opposing-token sale.
    function _aeroAssets(QuoteState memory original, uint256 shares) private view returns (uint256) {
        QuoteState memory q = abi.decode(abi.encode(original), (QuoteState));
        _aeroCompound(q);
        uint256 lp = BetterMath._convertToAssetsDown(shares, q.actualLp, q.supply, ERC4626Repo._decimalOffset());
        if (q.asset == q.pool) return lp;
        uint256 side = q.asset == q.tokens[0] ? 0 : 1;
        return AerodromeUtils._quoteWithdrawSwapWithFee(
            lp, q.poolSupply, q.reserves[side], q.reserves[1 - side], _aeroFee(q)
        );
    }

    function quoteTransition(bytes calldata state, Operation operation, uint256 amount)
        external view returns (bytes memory, uint256 amountIn, uint256 amountOut, uint256)
    {
        QuoteState memory q = _readAeroQuote(state);
        amountIn = amount;
        if (operation == Operation.ReceiveShares) {
            q.holderShares += amount;
            if (q.holderShares > q.supply) revert InvalidQuoteState();
            amountOut = amount;
        } else if (operation == Operation.DepositExactIn) {
            amountOut = _aeroDeposit(q, q.asset, amount);
            q.holderShares += amountOut;
        } else {
            _aeroCompound(q);
            uint256 side = q.asset == q.tokens[0] ? 0 : 1;
            if (operation == Operation.WithdrawExactOut) {
                uint256 needed = q.asset == q.pool ? amount : _quoteAeroLpToToken(
                    amount, q.poolSupply, q.reserves[side], q.reserves[1 - side], _aeroFee(q)
                );
                amountIn = BetterMath._convertToSharesUp(needed, q.actualLp, q.supply, ERC4626Repo._decimalOffset());
            }
            if (amountIn > q.holderShares) revert InsufficientQuoteShares(amountIn, q.holderShares);
            uint256 lp = BetterMath._convertToAssetsDown(amountIn, q.actualLp, q.supply, ERC4626Repo._decimalOffset());
            q.holderShares -= amountIn;
            q.supply -= amountIn;
            _aeroUpdateForVault(q);
            q.actualLp -= lp;
            amountOut = q.asset == q.pool ? lp : _aeroWithdraw(q, side, lp);
            q.bookedLp = q.actualLp;
            if (operation == Operation.WithdrawExactOut && amountOut < amount) revert InvalidQuoteState();
        }
        return (abi.encode(q), amountIn, amountOut, _aeroAssets(q, q.holderShares));
    }

    function quoteExternalDeposit(bytes calldata state, address tokenIn, uint256 amountIn)
        external view returns (bytes memory, uint256 sharesOut, uint256)
    {
        QuoteState memory q = _readAeroQuote(state);
        sharesOut = _aeroDeposit(q, tokenIn, amountIn);
        return (abi.encode(q), sharesOut, _aeroAssets(q, q.holderShares));
    }

    function _aeroDeposit(QuoteState memory q, address tokenIn, uint256 amount) private view returns (uint256 minted) {
        _aeroCompound(q);
        uint256 beforeLp = q.actualLp;
        uint256 received;
        if (tokenIn == q.pool) {
            _aeroUpdateForVault(q);
            q.actualLp += amount;
            received = amount;
        } else {
            if (tokenIn != q.tokens[0] && tokenIn != q.tokens[1]) revert UnsupportedQuoteAsset(tokenIn);
            if (q.actualLp != q.bookedLp) revert InvalidQuoteState();
            received = _aeroZap(q, tokenIn == q.tokens[0] ? 0 : 1, amount);
        }
        minted = BetterMath._convertToSharesDown(received, beforeLp, q.supply, ERC4626Repo._decimalOffset());
        q.supply += minted;
        q.bookedLp = q.actualLp;
    }

    function quoteExternalExchange(bytes calldata state, address tokenIn, uint256 amountIn)
        external view returns (bytes memory, uint256 amountOut, uint256)
    {
        QuoteState memory q = _readAeroQuote(state);
        uint256 side = q.asset == q.tokens[0] ? 0 : 1;
        if (q.asset == q.pool) {
            if (tokenIn != q.tokens[0] && tokenIn != q.tokens[1]) revert UnsupportedQuoteAsset(tokenIn);
            // The router mints directly to the separate recipient. It does not
            // transfer LP through this SE or checkpoint this SE's fee indexes.
            amountOut = _aeroZapTo(q, tokenIn == q.tokens[0] ? 0 : 1, amountIn, false);
        } else if (tokenIn == q.pool) {
            // The pass-through receives LP before forwarding it to the router.
            // Both transfers checkpoint the vault's already-earned LP fees.
            _aeroUpdateForVault(q);
            q.actualLp += amountIn;
            _aeroUpdateForVault(q);
            q.actualLp -= amountIn;
            amountOut = _aeroWithdraw(q, side, amountIn);
        } else if (tokenIn == q.tokens[1 - side]) {
            amountOut = _aeroSwap(q, 1 - side, amountIn);
        } else revert UnsupportedQuoteAsset(tokenIn);
        if (q.actualLp != q.bookedLp) revert InvalidQuoteState();
        return (abi.encode(q), amountOut, _aeroAssets(q, q.holderShares));
    }

    /// @dev Mirror Pool._updateFor before every LP balance mutation.
    function _aeroUpdateForVault(QuoteState memory q) private pure {
        for (uint256 i; i < 2; ++i) {
            q.claimable[i] += Math.mulDiv(q.actualLp, q.indexes[i] - q.suppliedIndexes[i], 1e18);
            q.suppliedIndexes[i] = q.indexes[i];
        }
    }

    function _aeroCompound(QuoteState memory q) private view {
        _aeroUpdateForVault(q);
        uint256 total0 = q.claimable[0] + q.excess[0];
        uint256 total1 = q.claimable[1] + q.excess[1];
        q.claimable[0] = 0;
        q.claimable[1] = 0;
        q.excess[0] = 0;
        q.excess[1] = 0;
        if (total0 == 0 && total1 == 0) return;
        (uint256 proportional0, uint256 proportional1) = _proportionalDeposit(q.reserves[0], q.reserves[1], total0, total1);
        uint256 minted;
        if (proportional0 != 0 && proportional1 != 0) {
            minted = _aeroAddLiquidity(q, 0, proportional0, proportional1);
        }
        uint256[2] memory excess = [total0 - proportional0, total1 - proportional1];
        for (uint256 i; i < 2; ++i) {
            if (excess[i] > DEFAULT_DUST_THRESHOLD) minted += _aeroZap(q, i, excess[i]);
            else q.excess[i] = excess[i];
        }
        if (minted == 0) return;
        uint256 fee = BetterMath._percentageOfWAD(minted, VaultFeeOracleQueryAwareRepo._feeOracle().usageFeeOfVault(address(this)));
        if (fee != 0) {
            _aeroUpdateForVault(q);
            if (address(VaultFeeOracleQueryAwareRepo._feeOracle().feeTo()) != address(this)) q.actualLp -= fee;
        }
        q.bookedLp = q.actualLp;
    }

    function _aeroSwap(QuoteState memory q, uint256 side, uint256 amount) private view returns (uint256 output) {
        uint256 fee = _aeroFee(q);
        uint256 net = amount - Math.mulDiv(amount, fee, 10_000);
        output = Math.mulDiv(net, q.reserves[1 - side], q.reserves[side] + net);
        if (output == 0 || output >= q.reserves[1 - side]) revert InvalidQuoteState();
        q.balances[side] += amount;
        q.balances[1 - side] -= output;
        for (uint256 i; i < 2; ++i) {
            uint256 expected = q.reserves[i] - (i == side ? 0 : output);
            uint256 gross = q.balances[i] > expected ? q.balances[i] - expected : 0;
            uint256 collected = Math.mulDiv(gross, fee, 10_000);
            q.balances[i] -= collected;
            if (collected != 0) q.indexes[i] += Math.mulDiv(collected, 1e18, q.poolSupply);
        }
        q.reserves[0] = q.balances[0];
        q.reserves[1] = q.balances[1];
    }

    function _aeroZap(QuoteState memory q, uint256 side, uint256 amount) private view returns (uint256) {
        return _aeroZapTo(q, side, amount, true);
    }

    function _aeroZapTo(QuoteState memory q, uint256 side, uint256 amount, bool toVault) private view returns (uint256) {
        uint256 sold = ConstProdUtils._swapDepositSaleAmt(amount, q.reserves[side], _aeroFee(q), 10_000);
        uint256 bought = _aeroSwap(q, side, sold);
        return _aeroAddLiquidityTo(q, side, amount - sold, bought, toVault);
    }

    function _aeroAddLiquidity(QuoteState memory q, uint256 side, uint256 desiredA, uint256 desiredB)
        private pure returns (uint256 minted)
    {
        return _aeroAddLiquidityTo(q, side, desiredA, desiredB, true);
    }

    function _aeroAddLiquidityTo(QuoteState memory q, uint256 side, uint256 desiredA, uint256 desiredB, bool toVault)
        private pure returns (uint256 minted)
    {
        (uint256 a, uint256 b) = _proportionalDeposit(q.reserves[side], q.reserves[1 - side], desiredA, desiredB);
        q.balances[side] += a;
        q.balances[1 - side] += b;
        uint256 amount0 = q.balances[0] - q.reserves[0];
        uint256 amount1 = q.balances[1] - q.reserves[1];
        if (q.poolSupply == 0) {
            minted = Math.sqrt(amount0 * amount1) - 1_000;
            q.poolSupply = 1_000;
        } else {
            minted = Math.min(Math.mulDiv(amount0, q.poolSupply, q.reserves[0]), Math.mulDiv(amount1, q.poolSupply, q.reserves[1]));
        }
        if (minted == 0) revert InvalidQuoteState();
        if (toVault) {
            _aeroUpdateForVault(q);
            q.actualLp += minted;
        }
        q.poolSupply += minted;
        q.reserves[0] = q.balances[0];
        q.reserves[1] = q.balances[1];
    }

    function _aeroWithdraw(QuoteState memory q, uint256 side, uint256 lp) private view returns (uint256 output) {
        uint256 burned = lp + q.poolHeldLp;
        q.poolHeldLp = 0;
        uint256 a = Math.mulDiv(burned, q.balances[side], q.poolSupply);
        uint256 b = Math.mulDiv(burned, q.balances[1 - side], q.poolSupply);
        if (a == 0 || b == 0) revert InvalidQuoteState();
        q.poolSupply -= burned;
        q.balances[side] -= a;
        q.balances[1 - side] -= b;
        q.reserves[0] = q.balances[0];
        q.reserves[1] = q.balances[1];
        output = a + _aeroSwap(q, 1 - side, b);
    }
}

// SPDX-License-Identifier: BSL-1.1
pragma solidity ^0.8.0;
import {IStandardExchangeTransitionQuote, IStandardExchangeExternalQuote} from "contracts/interfaces/IStandardExchangeTransitionQuote.sol";
import {AerodromeStandardExchangeQuoteTarget} from "contracts/protocols/dexes/aerodrome/v1/AerodromeStandardExchangeQuoteTarget.sol";
import {IStandardizedYield} from "@crane/contracts/protocols/perps/pendle/interfaces/IStandardizedYield.sol";
import {ConstantProductStandardYieldTarget} from "contracts/vaults/standard/sy/ConstantProductStandardYieldTarget.sol";
import {NativeStandardYieldSelectors} from "contracts/vaults/standard/sy/NativeStandardYieldSelectors.sol";


import {IFacet} from "@crane/contracts/interfaces/IFacet.sol";
import {IStandardExchangeOut} from "@crane/contracts/interfaces/IStandardExchangeOut.sol";
import {
    AerodromeStandardExchangeOutQueryTarget
} from "contracts/protocols/dexes/aerodrome/v1/AerodromeStandardExchangeOutQueryTarget.sol";

/// @notice Exact-output previews and native SY adapters using the installed standard routes.
contract AerodromeStandardExchangeOutQueryFacet is AerodromeStandardExchangeOutQueryTarget, AerodromeStandardExchangeQuoteTarget, ConstantProductStandardYieldTarget, IFacet {
    function facetName() public pure returns (string memory name) {
        return type(AerodromeStandardExchangeOutQueryFacet).name;
    }

    function facetInterfaces() public pure virtual returns (bytes4[] memory interfaces) {
        interfaces = new bytes4[](3);
        interfaces[0] = type(IStandardizedYield).interfaceId;
        interfaces[1] = type(IStandardExchangeTransitionQuote).interfaceId;
        interfaces[2] = type(IStandardExchangeExternalQuote).interfaceId;
    }

    function facetFuncs() public pure virtual returns (bytes4[] memory funcs) {
        funcs = new bytes4[](8);
        funcs[0] = IStandardExchangeOut.previewExchangeOut.selector;
        funcs[1] = IStandardExchangeTransitionQuote.quoteState.selector;
        funcs[2] = IStandardExchangeTransitionQuote.quoteAssets.selector;
        funcs[3] = IStandardExchangeTransitionQuote.quoteShareBalance.selector;
        funcs[4] = IStandardExchangeTransitionQuote.quoteTotalSupply.selector;
        funcs[5] = IStandardExchangeTransitionQuote.quoteTransition.selector;
        funcs[6] = IStandardExchangeExternalQuote.quoteExternalDeposit.selector;
        funcs[7] = IStandardExchangeExternalQuote.quoteExternalExchange.selector;
        funcs = NativeStandardYieldSelectors._append(funcs);
    }

    function facetMetadata()
        external
        pure
        returns (string memory name_, bytes4[] memory interfaces, bytes4[] memory functions)
    {
        name_ = facetName();
        interfaces = facetInterfaces();
        functions = facetFuncs();
    }
}

